<script>(()=>{const nav=document.querySelector('[data-e803-nav]');document.querySelector('[data-e803-toggle]')?.addEventListener('click',()=>nav?.classList.toggle('is-open'));document.querySelectorAll('[data-e803-tabs]').forEach(root=>root.querySelectorAll('[data-e803-tab]').forEach(btn=>btn.addEventListener('click',()=>{root.querySelectorAll('[data-e803-tab]').forEach(x=>x.classList.remove('is-active'));btn.classList.add('is-active')})));const box=document.querySelector('[data-e803-countdown]');if(box){let seconds=12*3600+39*60+26;setInterval(()=>{seconds=seconds>0?seconds-1:24*3600;const h=String(Math.floor(seconds/3600)).padStart(2,'0'),m=String(Math.floor(seconds%3600/60)).padStart(2,'0'),s=String(seconds%60).padStart(2,'0');box.innerHTML=`<b>00</b>:<b>${h}</b>:<b>${m}</b>:<b>${s}</b>`},1000)}})();</script>
